ben: TS draft:```ts
// stream-resume.ts
import Redwood from '@redwood/inference';
const client = new Redwood();

function decodeToken(t?: string) {
  if (!t) return null;
  try { return JSON.parse(Buffer.from(t, 'base64').toString()); } catch { return null; }
}

export async function resumeStream(prompt: string, resumeToken?: string) {
  let token = resumeToken;
  while (true) {
    const stream = await client.stream({ prompt, resume_token: token, chunk_limit: 8 });
    for await (const chunk of stream) {
      process.stdout.write(chunk.text);
      token = chunk.resume_token ?? token;
    }
    if (!token) break; // completed
  }
}
```

