li: Python retry + resume sketch:```py
# helpers.py
import time, uuid, base64, json
from functools import wraps
import requests

def idempotent_retry(max_tries=3, backoff=0.5):
    def deco(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            rid = str(uuid.uuid4())
            for i in range(max_tries):
                try:
                    headers = kwargs.pop('headers', {})
                    headers.update({'X-Request-Id': rid})
                    return f(*args, headers=headers, **kwargs)
                except (requests.ConnectionError, requests.Timeout) as e:
                    if i == max_tries - 1:
                        raise
                    time.sleep(backoff * (2 ** i))
        return wrapper
    return deco

# resume token helpers
def encode_resume(obj):
    return base64.b64encode(json.dumps(obj).encode()).decode()

def decode_resume(token):
    return json.loads(base64.b64decode(token).decode())
```

# usage example
```py
# paginate_resume.py
