// resume_stream.go
package main

import (
  "context"
  "encoding/base64"
  "encoding/json"
  "fmt"
  "time"
)

type ResumeToken struct {
  Page  int    `json:"page"`
  Chunk string `json:"chunk_id"`
}

func decodeToken(t string) (*ResumeToken, error) {
  b, err := base64.StdEncoding.DecodeString(t)
  if err != nil { return nil, err }
  var r ResumeToken
  if err := json.Unmarshal(b, &r); err != nil { return nil, err }
  return &r, nil
}

func streamWithResume(ctx context.Context, client *Client, token string) {
  ctx, cancel := context.WithTimeout(ctx, 45*time.Second)
  defer cancel()
  ch := client.Stream(ctx, StreamParams{ResumeToken: token})
  for msg := range ch { // channel of messages
    fmt.Print(msg.Text)
    if msg.ResumeToken != "" { saveToken(msg.ResumeToken) }
  }
}
```

